import type { MachineTable } from '../packages/machine/src/index.js';

export function renderMachineTables(tables: readonly MachineTable<{ kind: string }, { type: string }>[]): string {
  const lines = [
    '# State machine tables',
    '',
    'Generated from `test/state-machines.registry.ts`. Do not edit this file by hand.',
    '',
    'Regenerate with `UPDATE_STATE_MACHINES=1 pnpm exec vitest run test/state-machines.test.ts`.',
    'The convention and owning specs are in [state-machines.md](state-machines.md).',
    'Unlisted events return the same state. Listed self-transitions may update payloads.',
    '',
  ];
  const ids = new Set<string>();
  for (const table of [...tables].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0)) {
    if (ids.has(table.id)) throw new Error(`Duplicate machine id: ${table.id}`);
    ids.add(table.id);
    lines.push(
      `## ${table.id}`,
      '',
      `Initial: \`${table.initial}\`. Final: ${table.final.length ? [...table.final].sort().map((kind) => `\`${kind}\``).join(', ') : 'none'}.`,
      '',
      '| State | Event | Targets |',
      '| --- | --- | --- |',
    );
    for (const from of Object.keys(table.on).sort()) {
      const row = table.on[from]!;
      const events = Object.keys(row).filter((event) => row[event]?.length).sort();
      if (!events.length) lines.push(`| \`${from}\` | — | — |`);
      for (const event of events) {
        lines.push(`| \`${from}\` | \`${event}\` | ${[...row[event]!].sort().map((kind) => `\`${kind}\``).join(', ')} |`);
      }
    }
    lines.push('');
  }
  return lines.join('\n');
}
